// ============================================================
//   gifted-btns (panel build) — native-flow button sender
// ------------------------------------------------------------
//   Clean-room, dependency-free implementation of the
//   sendButtons / sendInteractiveMessage API used by Pixel.
//
//   The published `gifted-btns` package is obfuscated and runs
//   its payload through eval(), so it is not installed on this
//   panel — the bot holds WhatsApp sessions and cannot run
//   unauditable code. This module produces the same message:
//
//     interactiveMessage.nativeFlowMessage + additionalNodes
//     stanza (biz > interactive[native_flow v1] > native_flow
//     v9 mixed) — without that stanza WhatsApp relays the
//     message but silently refuses to render the buttons.
//
//   If the socket or the installed baileys build cannot send
//   native flow, it degrades to a plain text listing.
// ============================================================
'use strict';

function resolveWa() {
  try { return require('../@whiskeysockets/baileys'); } catch {}
  try { return require('@whiskeysockets/baileys'); } catch {}
  try { return require('baileys'); } catch {}
  return null;
}

const btn = {
  url(display_text, url, merchant_url) {
    return { name: 'cta_url', buttonParamsJson: JSON.stringify({ display_text, url, merchant_url: merchant_url || url }) };
  },
  copy(display_text, copy_code) {
    return { name: 'cta_copy', buttonParamsJson: JSON.stringify({ display_text, copy_code }) };
  },
  call(display_text, phone_number) {
    return { name: 'cta_call', buttonParamsJson: JSON.stringify({ display_text, phone_number }) };
  },
  reply(display_text, id) {
    return { name: 'quick_reply', buttonParamsJson: JSON.stringify({ display_text, id }) };
  },
  list(list_button_text, sections) {
    return { name: 'single_select', buttonParamsJson: JSON.stringify({ title: list_button_text, sections }) };
  },
};

function flatten(payload) {
  if (!payload) return '';
  if (typeof payload === 'string') return payload;
  if (payload.text) return String(payload.text);
  if (payload.caption) return String(payload.caption);
  if (Array.isArray(payload)) return payload.map(flatten).filter(Boolean).join('\n');
  if (payload.sections) {
    return payload.sections
      .map((s) => (s.title ? s.title + '\n' : '') + (s.rows || []).map((r) => '• ' + (r.title || r.id || '')).join('\n'))
      .join('\n\n');
  }
  if (payload.buttons) return payload.buttons.map((b) => '• ' + (b.text || b.display_text || b.id || '')).join('\n');
  return '';
}

const INTERACTIVE_NODES = [
  {
    tag: 'biz',
    attrs: {},
    content: [
      {
        tag: 'interactive',
        attrs: { type: 'native_flow', v: '1' },
        content: [{ tag: 'native_flow', attrs: { v: '9', name: 'mixed' } }],
      },
    ],
  },
];

async function sendButtons(sock, jid, options = {}, extra = {}) {
  const opts = { ...(options || {}), ...(extra && extra.buttons ? extra : {}) };
  const {
    text = '', footer = '', title, subtitle, buttons, interactiveButtons, contextInfo, quoted, image,
  } = opts;

  let list = buttons || interactiveButtons || [];
  // tolerate the older `{ id, text }` shorthand
  list = (list || []).map((b) => {
    if (b && typeof b.name === 'string' && typeof b.buttonParamsJson === 'string') return b;
    if (b && b.text) return btn.reply(String(b.text), String(b.id || b.text));
    return b;
  }).filter(Boolean);

  const wa = resolveWa();
  const quotedArg = quoted || (extra && extra.quoted);

  if (wa && typeof wa.generateWAMessageFromContent === 'function' && sock && typeof sock.relayMessage === 'function' && list.length) {
    // Media header: image rides inside the same bubble as the caption + buttons.
    let header = { title: title || '', subtitle: subtitle || '', hasMediaAttachment: false };
    if (image && typeof wa.prepareWAMessageMedia === 'function' && sock.waUploadToServer !== undefined) {
      try {
        const media = await wa.prepareWAMessageMedia(
          image.url ? { image: { url: image.url } } : { image: image.buffer || image },
          { upload: sock.waUploadToServer },
        );
        if (media && media.imageMessage) {
          header = { title: title || '', subtitle: subtitle || '', hasMediaAttachment: true, imageMessage: media.imageMessage };
        }
      } catch {}
    }

    const content = {
      interactiveMessage: {
        header,
        ...(text ? { body: { text } } : {}),
        ...(footer ? { footer: { text: footer } } : {}),
        ...(contextInfo && typeof contextInfo === 'object' ? { contextInfo } : {}),
        nativeFlowMessage: { buttons: list, messageParamsJson: '', messageVersion: 1 },
      },
    };
    const full = wa.generateWAMessageFromContent(jid, content, { quoted: quotedArg, userJid: sock.user && sock.user.id });
    await sock.relayMessage(jid, full.message, { messageId: full.key.id, additionalNodes: INTERACTIVE_NODES });
    return full;
  }

  // fallback: still deliver the content (image caption when an image was given)
  const body = text || flatten({ buttons: list });
  if (image) {
    const media = image.url ? { url: image.url } : (image.buffer || image);
    try { return await sock.sendMessage(jid, { image: media, caption: body }, { quoted: quotedArg }); } catch {}
  }
  return sock.sendMessage(jid, { text: body }, { quoted: quotedArg });
}

const sendInteractiveMessage = sendButtons;

async function sendRaw(sock, jid, options = {}) {
  const { text = '', image, caption, contextInfo, quoted } = options;
  const message = image
    ? { image, caption: caption === undefined ? text : caption, ...(contextInfo ? { contextInfo } : {}) }
    : { text, ...(contextInfo ? { contextInfo } : {}) };
  return sock.sendMessage(jid, message, { quoted });
}

module.exports = { sendButtons, sendInteractiveMessage, sendRaw, btn, flatten };
